content.text:
            jobs.append({
                "id": job_id,
                "packet": index,
                "connection": connection_id,
                "slot": slot,
                "generation": slot_generation[slot],
                "lane": lane,
                "start": start,
                "done": done,
                "window": [[row[0], row[1]] for row in snapshot],
                "logits": logits,
                "prediction": prediction,
                "status": None,
            })
            heapq.heappush(pending, (done, job_id))
            slot_anchor[slot] = now
            slot_backlog[slot] = 0

        packet_rows.append({
            "index": index,
            "connection": connection_id,
            "generation": slot_generation[slot],
            "forward": forward,
            "decision": decision,
            "credit": credit,
            "job": job_id,
        })

    # final drain: finish every remaining job in (done, id) order
    while pending:
        done, job_id = heapq.heappop(pending)
        finish_job(job_id)

    connection_rows = []
    for i, conn in enumerate(connections):
        counts = votes[i]
        prediction = None
        if counters[i] > 0:
            best = 0
            for c in range(1, classes):
                if counts[c] > counts[best]:
                    best = c
            prediction = best
        connection_rows.append({
            "id": conn["id"],
            "split": conn["split"],
            "label": conn["label"],
            "packets": counters[i],
            "votes": counts,
            "prediction": prediction,
        })

    reports = _build_reports(connection_rows, classes)

    return {
        "packets": packet_rows,
        "jobs": jobs,
        "connections": connection_rows,
        "reports": reports,
    }


def _build_reports(connection_rows, classes):
    reports = {}
    for split in ("dev", "eval"):
        confusion = [[0] * classes for _ in range(classes)]
        observed = 0
        for row in connection_rows:
            if row["split"] != split:
                continue
            if row["packets"] <= 0:
                continue
            observed += 1
            confusion[row["label"]][row["prediction"]] += 1
        total = Fraction(0)
        for c in range(classes):
            true_positive = confusion[c][c]
            false_positive = 0
            for r in range(classes):
                false_positive += confusion[r][c]
            false_positive -= true_positive
            false_negative = sum(confusion[c]) - true_positive
            denominator = 2 * true_positive + false_positive + false_negative
            if denominator > 0:
                total += Fraction(2 * true_positive, denominator)
        macro = total / classes
        reports[split] = {
            "connections": observed,
            "confusion": confusion,
            "macro_f1": [macro.numerator, macro.denominator],
        }
    return reports


