# entry point
# --------------------------------------------------------------------------

def _run(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise InvalidInput()
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        raise InvalidInput()
    try:
        doc = json.loads(text, object_pairs_hook=_no_duplicate_keys,
                         parse_constant=_reject_constant)
    except InvalidInput:
        raise
    except (ValueError, RecursionError):
        raise InvalidInput()
    config, model, connections, packets = validate_document(doc)
    return replay(config, model, connections, packets)


def main():
    try:
        raw = sys.stdin.buffer.read()
    except Exception:
        raw = b""
    payload = ERROR_DOC
    try:
        result = _run(raw)
        payload = json.dumps(result, separators=(",", ":"))
    except Exception:
        payload = ERROR_DOC
    try:
        sys.stdout.write(payload)
        sys.stdout.write("\n")
        sys.stdout.flush()
    except Exception:
        pass
    return 0


if __name__ == "__main__":
    sys.exit(main())
